CREATE TABLE tenants (id VARCHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, revision BIGINT NOT NULL DEFAULT 0, query_limit BIGINT NOT NULL DEFAULT 1000, queries_used BIGINT NOT NULL DEFAULT 0, queries_reserved BIGINT NOT NULL DEFAULT 0);
CREATE TABLE members (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(200) NOT NULL, role VARCHAR(32) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE credentials (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, subject_id VARCHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL, digest VARCHAR(64) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, expires_at TIMESTAMP NULL);
CREATE TABLE knowledge_bases (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(200) NOT NULL, description TEXT NOT NULL, language VARCHAR(20) NOT NULL DEFAULT 'zh', owner_id VARCHAR(36) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', revision BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions (tenant_id VARCHAR(36) NOT NULL, resource_id VARCHAR(36) NOT NULL, subject_id VARCHAR(36) NOT NULL, action VARCHAR(16) NOT NULL, PRIMARY KEY(tenant_id,resource_id,subject_id,action));
CREATE TABLE documents (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, kb_id VARCHAR(36) NOT NULL, title VARCHAR(250) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', restricted BOOLEAN NOT NULL DEFAULT FALSE, published_version VARCHAR(36), revision BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE document_versions (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, document_id VARCHAR(36) NOT NULL, object_key VARCHAR(300) NOT NULL, filename VARCHAR(250) NOT NULL, digest VARCHAR(64) NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'QUEUED', revision BIGINT NOT NULL DEFAULT 0, ever_published BOOLEAN NOT NULL DEFAULT FALSE, model_identity VARCHAR(500), valid_from TIMESTAMP NULL, valid_until TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE chunks (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, version_id VARCHAR(36) NOT NULL, ordinal_no INT NOT NULL, source_text TEXT NOT NULL, content TEXT NOT NULL, location TEXT NOT NULL, token_count INT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, revision BIGINT NOT NULL DEFAULT 0, UNIQUE(version_id,ordinal_no));
CREATE TABLE jobs (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, version_id VARCHAR(36) NOT NULL, kind VARCHAR(20) NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'QUEUED', attempts INT NOT NULL DEFAULT 0, lease_token VARCHAR(36), lease_until TIMESTAMP NULL, error_code VARCHAR(100), request_key VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,request_key));
CREATE TABLE outbox (id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL, sent BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE publications (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, document_id VARCHAR(36) NOT NULL, version_id VARCHAR(36) NOT NULL, actor_id VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(200) NOT NULL, description TEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 0, published BOOLEAN NOT NULL DEFAULT FALSE, allow_degraded BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE application_bindings (tenant_id VARCHAR(36) NOT NULL, application_id VARCHAR(36) NOT NULL, kb_id VARCHAR(36) NOT NULL, PRIMARY KEY(application_id,kb_id));
CREATE TABLE usage_events (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, application_id VARCHAR(36), subject_id VARCHAR(36) NOT NULL, request_key VARCHAR(100) NOT NULL, resource_type VARCHAR(32) NOT NULL, amount BIGINT NOT NULL, state VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,subject_id,request_key,resource_type));
CREATE TABLE answers (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, subject_id VARCHAR(36) NOT NULL, application_id VARCHAR(36), question TEXT NOT NULL, content TEXT NOT NULL, feedback VARCHAR(16), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE answer_evidence (answer_id VARCHAR(36) NOT NULL, document_id VARCHAR(36) NOT NULL, version_id VARCHAR(36) NOT NULL, chunk_id VARCHAR(36) NOT NULL, PRIMARY KEY(answer_id,chunk_id));
CREATE TABLE audit_events (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, actor_id VARCHAR(36) NOT NULL, action VARCHAR(50) NOT NULL, resource_id VARCHAR(36) NOT NULL, details TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_docs_tenant_kb ON documents(tenant_id,kb_id);
CREATE INDEX idx_versions_document ON document_versions(tenant_id,document_id);
CREATE INDEX idx_chunks_version ON chunks(tenant_id,version_id);
CREATE INDEX idx_jobs_state ON jobs(state,lease_until);
CREATE INDEX idx_audit_tenant ON audit_events(tenant_id,created_at);
